CREATE FUNCTION hiring_private.hiring_admin_freeze_bank(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.question_bank; r record; snapshot uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO b FROM public.question_bank WHERE id=_id FOR UPDATE; FOR r IN SELECT id FROM public.job_questions WHERE question_id=_id LOOP INSERT INTO public.question_bank(category,type,label,help_text,options,max_length,knockout_rule,is_active) VALUES('__job_snapshot',b.type,b.label,b.help_text,b.options,b.max_length,b.knockout_rule,false) RETURNING id INTO snapshot; UPDATE public.job_questions SET question_id=snapshot,label_override=coalesce(label_override,b.label) WHERE id=r.id; INSERT INTO public.hiring_question_sources(job_question_id,bank_question_id) VALUES(r.id,_id) ON CONFLICT(job_question_id) DO NOTHING; END LOOP; END $$;
CREATE FUNCTION public.hiring_admin_freeze_bank(_id uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT hiring_private.hiring_admin_freeze_bank(_id) $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_admin_freeze_bank(uuid),public.hiring_admin_freeze_bank(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION hiring_private.hiring_admin_freeze_bank(uuid),public.hiring_admin_freeze_bank(uuid) TO authenticated,service_role;